-- Sliding Window Maximum (Hard)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$sliding-window-maximum$q$, $q$Sliding Window Maximum$q$, $q$A window of size k slides from the left end of the array to the right end, one position at a time. For every position of the window, report the largest value inside it.$q$, $q$Hard$q$, $q$Queues$q$, 'code', ARRAY[$q$deque$q$, $q$sliding-window$q$, $q$monotonic-queue$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n and k.\n    # Line 2: n integers.\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n and k.\n// Line 2: n integers.\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n and k.\n        // Line 2: n integers.\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n and k.\n    // Line 2: n integers.\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n and k.\n    // Line 2: n integers.\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "8 3\n1 3 -1 -3 5 3 6 7", "output": "3 3 5 5 6 7", "explanation": "Windows: [1 3 -1] [3 -1 -3] [-1 -3 5] [-3 5 3] [5 3 6] [3 6 7]."}, {"input": "4 4\n2 9 1 4", "output": "9", "explanation": "One window covering the whole array."}]$q$::jsonb, ARRAY[$q$1 ≤ k ≤ n ≤ 10 000$q$, $q$-10^6 ≤ a[i] ≤ 10^6$q$]::text[], 50, 1018, 2000, 262144, $q$Line 1: n and k.
Line 2: n integers.$q$, $q$n - k + 1 integers separated by spaces: the maximum of each window, left to right.$q$, $q$Taking the max of every window costs O(n·k). Use a monotonic deque of indices whose values are in decreasing order. For each new element, pop smaller values from the back, push the index, drop the front if it left the window, and the front is the window maximum. Each index enters and leaves once: O(n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

